const mounted=[],originalFetch=globalThis.fetch
function element(tag){const n={tag,props:{},children:[],addEventListener(){},removeEventListener(){},getRootNode(){return {}},style:{}};Object.defineProperty(n,'options',{get(){return nodes(n,x=>x.tag==='option')}});return n}
const nodes=(n,p)=>[...(p(n)?[n]:[]),...(n.children||[]).flatMap(c=>nodes(c,p))]
const text=n=>(n.text||'')+(n.children||[]).map(text).join(' ')
const renderer=createRenderer({createElement:element,createText:text=>({text}),createComment:()=>({}),setText:(n,t)=>n.text=t,setElementText:(n,t)=>{n.text=t;n.children=[]},patchProp:(n,k,o,v)=>{n.props[k]=v;if(k==='value')n.value=v},insert:(n,p,a)=>{if(n.parent){const i=n.parent.children.indexOf(n);if(i>=0)n.parent.children.splice(i,1)}n.parent=p;const i=a?p.children.indexOf(a):-1;if(i<0)p.children.push(n);else p.children.splice(i,0,n)},remove:n=>{if(n?.parent)n.parent.children.splice(n.parent.children.indexOf(n),1)},parentNode:n=>n.parent,nextSibling:n=>{const a=n.parent?.children||[];return a[a.indexOf(n)+1]||null}})
const settle=async()=>{for(let i=0;i<40;i++){await Promise.resolve();await nextTick()}}
const response=(data,status=200)=>({ok:status<400,status,json:async()=>data})
before(()=>{globalThis.Document=class {};globalThis.ShadowRoot=class {};globalThis.document={}})
afterEach(()=>{mounted.splice(0).forEach(a=>a.unmount());globalThis.fetch=originalFetch})
async function mount(Page,{props={},en=false,hq=true,own=null,renderErrors=null,path='/stores/A/workforce/supplemental-payroll'}={}){const router=createRouter({history:createMemoryHistory(),routes:[{path:'/stores/:storeId/workforce/:page',component:Page},{path:'/:pathMatch(.*)*',component:{render:()=>null}}]});await router.push(path);await router.isReady();const root=element('root'),app=renderer.createApp({render:()=>h(Page,props)});if(renderErrors)app.config.errorHandler=e=>renderErrors.push(String(e));app.use(router);app.use(createI18n({legacy:false,locale:en?'en':'zh-CN',messages:{}}));app.provide(workforceKey,{store:ref('A'),home:ref({headOffice:hq,employeeManage:false,companies:[{id:'C',name:'Company'}],stores:[{id:'A',companyId:'C',name:'Store'}],myself:own?{id:own}:null}),api:()=>workforceApi('A'),refresh:async()=>{}});app.mount(root);mounted.push(app);await settle();return {root,app,router}}
const button=(r,label)=>{const n=nodes(r,n=>n.tag==='button'&&text(n).trim()===label)[0];assert.ok(n,'missing button '+label);return n}
const click=async(r,label)=>{const n=button(r,label);if(n.props.onClick)await n.props.onClick();else {let p=n.parent;while(p&&p.tag!=='form')p=p.parent;await p?.props.onSubmit?.({preventDefault(){}})}await settle()}
const field=async(r,label,value)=>{const n=nodes(r,n=>n.props?.['aria-label']===label)[0];assert.ok(n,'missing field '+label);for(const update of [n.props['onUpdate:modelValue']].flat())update(value);await n.props.onChange?.();await settle()}
const labelField=async(r,label,value)=>{const l=nodes(r,n=>n.tag==='label'&&text(n).trim().startsWith(label))[0];assert.ok(l,'missing label '+label);const n=nodes(l,n=>['input','textarea','select'].includes(n.tag))[0];for(const update of [n.props['onUpdate:modelValue']].flat())update(value);await n.props.onChange?.();await settle()}
