function managerApi({batches=[batch],requests=[request],own=null,onWrite}={}){return async(u,o)=>{const url=String(u);if(o?.method!=='GET'&&o?.body)return onWrite?onWrite(url,JSON.parse(o.body),o):response(detail());if(url.endsWith('/payroll-home'))return response({companies:[{id:'C',name:'Company'}],employeeId:own});if(url.includes('/pay-change-requests?'))return response(requests);if(url.includes('/supplemental-batches?'))return response(batches);if(url.includes('/supplemental-batches/'))return response(detail({batch:batches[0]||batch}));if(url.includes('/pay-profiles?'))return response({items:[],employees:[{id:'E',name:'Alice'}]});if(url.endsWith('/salary-templates?companyId=C'))return response([]);if(url.includes('/statutory-remittances?'))return response([]);return response([])}}

test('approved exact proposal creates a batch without resubmitting money or original payments',async()=>{const writes=[];globalThis.fetch=managerApi({onWrite:(u,b)=>{writes.push({u,b});return response(detail({batch:{...batch,id:u.split('/').at(-1),status:'draft',calculation:null}}))}});const {root}=await mount(SupplementalPayroll);await field(root,'已批准补发申请','R');await field(root,'精确补发方案','P');await click(root,'建立补发批次');assert.deepEqual(Object.keys(writes[0].b).sort(),['commandId','companyId','employeeId','expectedVersion','hash','proposalId','requestId','revision'].sort());assert.equal(writes[0].b.hash,'approved-hash');assert.equal(writes[0].b.revision,3);assert.match(text(root),/原贡献|2026-02/);assert.equal(button(root,'计算补发').props.disabled,false)})
