 const {root}=await mount(SupplementalPayroll);await field(root,'已批准补发申请',change.id);await field(root,'精确补发方案',change.content.supplemental[0].id);await click(root,'建立补发批次');await click(root,'计算补发');await click(root,'确认并冻结补发');await click(root,'发布补发工资单');await field(root,'现金付款金额','30.00');await field(root,'付款说明','cash paid');await click(root,'保存付款登记');assert.equal(currentBatch.status,'published');assert.equal(paid[0].amount,'30.00');assert.equal(writes.filter(w=>w.b.action==='approve').length,1);assert.equal(writes.filter(w=>w.url.includes('/supplemental-batches/')&&!w.url.includes('/payments/')&&!w.url.endsWith('/actions'))[0].b.hash,'new-approved-snapshot');assert.ok(writes.every(w=>!w.url.includes('/payroll-batches/')))
