test('Contract2 recovery selects only real same-company employee original-year reconciliations and sends exact id',async()=>{const writes=[],good={...reconciliation,id:recoveryReconciliation},rows=[good,{...good,id:'wrong-company',companyId:'OTHER'},{...good,id:'wrong-employee',employeeId:'OTHER'},{...good,id:'wrong-year',year:2025}];const api=statutoryApi((u,b)=>{writes.push({u,b});return response({...statutoryFacts,evidence:b})});globalThis.fetch=async(u,o)=>String(u).includes('/aw-reconciliations?')?response(rows.map(reconciliation=>({reconciliation,balances:[monthBalance],settled:false}))):api(u,o);const {root}=await factsPage();await labelField(root,'追回成因','aw_statutory_reassessment');await activeClick(root,'读取可关联AW复核');const options=nodes(root,n=>n.tag==='option');assert.ok(options.some(n=>n.props.value===recoveryReconciliation));assert.ok(options.every(n=>!['wrong-company','wrong-employee','wrong-year'].includes(n.props.value)));await field(root,'原事实凭证','reviewed legal facts');await field(root,'关联原年度AW复核','wrong-company');await activeClick(root,'保存法定事实修订');assert.equal(writes.length,0);assert.match(text(root),/请选择已读取且匹配/);await field(root,'关联原年度AW复核',recoveryReconciliation);await activeClick(root,'保存法定事实修订');assert.equal(writes[0].b.recovery.reconciliationId,recoveryReconciliation);assert.match(text(root),/不自动从后续工资收回/);assert.match(text(root),/未知/)})

