test('employee pay entry highlights the latest published period and distinguishes payable from payment',async()=>{
 globalThis.fetch=async u=>{const url=String(u);if(url.endsWith('/my-latest-payslip'))return response({slip:{batchId:'N',companyName:'Company',month:'2025-12',netPay:'800.00',paidAmount:'0.00',status:'published'}});if(url.includes('/my-payslips?year='))return response([{batchId:'N',companyName:'Company',month:'2025-12',netPay:'800.00',paidAmount:'0.00',status:'published'}]);return response([])};
 const {root}=await mount(PayslipList);assert.match(text(root),/本期应实发/);assert.match(text(root),/2025-12/);assert.match(text(root),/800.00/);assert.match(text(root),/发布不代表已付款/);
});

test('a more recent supplemental payslip determines the initial employee viewing year',async()=>{const paths=[];globalThis.fetch=async u=>{const url=String(u);paths.push(url);if(url.endsWith('/my-latest-payslip'))return response({slip:{batchId:'N',month:'2025-12'},supplementalMonth:'2026-10'});return response([])};await mount(PayslipList);assert.ok(paths.some(p=>p.includes('/my-payslips?year=2026')));assert.equal(paths.some(p=>p.includes('/my-payslips?year=2025')),false)});
